import { cookies } from "next/headers";
import { Metadata } from "next";
import Image from "next/image";
import "@styles/theme/main.global.css";
import "boxicons/css/boxicons.min.css";
import TextArea from "@components/functional-comps/textareaa";

export const metadata: Metadata = {
  title: "Woah AI",
  description: "Chat with you AI Partner with Privacy.",
};

type Theme = "dark" | "light";

export default async function Home() {
  const cookieStore = await cookies();
  const cookieTheme = cookieStore.get("theme")?.value;
  const darkTheme = cookieTheme === "dark";

  return (
    <main
      className={`home-page ${
        darkTheme
          ? "bg-dark-black-primary text-dark-white-primary"
          : "bg-light-white-primary text-light-black-primary"
      } h-[100%] w-[100%] `}
    >
      <div className="h-full flex flex-col w-[100%]">
        <div className="h-[50%] w-[100%] flex flex-col justify-end items-center gap-3">
          <div className={`min-w-[300px] max-w-[600px] w-[100%] px-4 text-center font-bold font-sans text-[24px]`}>Introducing with WoahAI-2</div>
          <div className={`min-w-[300px] max-w-[600px] w-[100%] px-4 text-center pb-2.5 text-[14px] ${darkTheme ? "text-dark-white-secondary" : "text-light-black-secondary"}`} >WoahGPT now has our smartest, fastest, most useful model yet, with thinking built in — so you get the best answer, every time.</div>
        </div>
        <div className="h-[50%] w-[100%] flex flex-col justify-start items-center">
          <div className="min-w-[300px] max-w-[690px] w-[100%] px-4">
            <TextArea />
          </div>
        </div>
      </div>
    </main>
  );
}
